//! 🧪️ The actual Layout lender preserves original handles, parent identity and receipt funding.
use super::*;
use semio_framework_io_ports::erase_child_admission_source;
use semio_framework_value::retained_clone::RetainedCloneSource;
fn generous()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:16*1024*1024,maximum_capacity_bytes:16*1024*1024,maximum_release_bytes:16*1024*1024,maximum_depth:256}}
fn exact(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
#[test]fn actual_parent_member_handles_are_lent_only_after_the_original_quote_is_funded(){let laws:serde_json::Value=serde_json::from_str(include_str!("../../../../../../../../../../../../../🧰️framework/🛍️products/💻️os/🔨️modules/🔌️plugin/📜️declaration/🪆️child/📖️vector/🧪️.json")).unwrap();assert_eq!(laws["cases"].as_array().unwrap().len(),17);let fixture:serde_json::Value=serde_json::from_str(include_str!("../../../../🧪️tests/🧫️fixtures/✅️validation/🔣️.json")).unwrap();for ordinal in [0,1]{for unicode in [false,true]{let mut document:LayoutSnapshot=serde_json::from_value(fixture["base"].clone()).unwrap();let reference=&laws["base"]["reference"];let child_id=if unicode{"drawing Grüße 🌍"}else{reference["childId"].as_str().unwrap()};let member:crate::LayoutDrawingMember=serde_json::from_value(serde_json::json!({"handle":{"childId":child_id,"target":{"artifactId":reference["artifactId"],"dialect":laws["base"]["capability"]}}})).unwrap();if ordinal==0{document.background_drawing=Some(member)}else{document.pages[0].background_drawing=Some(member)}let(mut source,_)=RetainedCloneSource::admit_owned(document,(),generous()).unwrap_or_else(|_|panic!("actual Layout source"));{let original=source.borrow();let parent=original.get();let handle=if ordinal==0{&parent.background_drawing.as_ref().unwrap().handle}else{&parent.pages[0].background_drawing.as_ref().unwrap().handle};let source=erase_child_admission_source(original,9);let d=LAYOUT_DRAWING_REFERENCE_LENDER.demand(ordinal);for axis in [0,1,2]{let mut g=exact(d);match axis{0=>g.maximum_items=0,1=>g.maximum_copy_bytes-=1,_=>g.maximum_depth-=1}let(result,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||LAYOUT_DRAWING_REFERENCE_LENDER.read(source,ordinal,g));let step=result.unwrap();assert!(!step.done&&step.reference.is_none());assert_eq!(step.progress,Default::default());assert_eq!(heap,(0,0));}let(result,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||LAYOUT_DRAWING_REFERENCE_LENDER.read(source,ordinal,exact(d)));let step=result.unwrap();assert!(step.progress.fits(exact(d)));assert_eq!(heap,(0,0));let actual=step.reference.unwrap();assert_eq!(actual.parent_identity,parent as*const _ as usize);assert_eq!(actual.identity,handle as*const _ as usize);assert_eq!(actual.child_id,child_id);assert_eq!(actual.slot,if ordinal==0{"backgroundDrawing"}else{"pages"});assert_eq!(actual.child_id.as_ptr(),handle.child_id.as_ptr());}while !source.terminal_is_empty(){let d=source.next_close_demand(generous().maximum_copy_bytes).unwrap();source.close_step(exact(d)).unwrap();}}}}
